import{_ as a,o,c as t,a5 as r}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 33 话 @starting-style：让「从无到有」也能平滑过渡","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.33-starting-style.md","filePath":"comics/css/EP.33-starting-style.md","lastUpdated":1793421609000}'),s={name:"comics/css/EP.33-starting-style.md"};function d(l,e,i,c,n,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-33-话-starting-style-让「从无到有」也能平滑过渡" tabindex="-1">漫画 · 第 33 话 @starting-style：让「从无到有」也能平滑过渡 <a class="header-anchor" href="#漫画-·-第-33-话-starting-style-让「从无到有」也能平滑过渡" aria-label="Permalink to &quot;漫画 · 第 33 话 @starting-style：让「从无到有」也能平滑过渡&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/22-starting-style">docs/css/22-starting-style.md</a> ｜ 原画：<a href="./EP.33-starting-style.svg">EP.33-starting-style.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。每个新插入的 DOM 都要写 <code>requestAnimationFrame</code> 拆帧加类，display 切换更是要强制 reflow，动画时长在 CSS 和 JS 里双写。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 <code>@starting-style</code> 与 <code>transition-behavior: allow-discrete</code>，一句声明让浏览器自动补帧。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱被「新元素入场动画」折磨：<code>appendChild</code> 后元素直接闪现，只能手动加 <code>.enter</code> 类再删掉；<code>display: none</code> 切换更是要先显示、强制 reflow、再过渡。标签君引入 <code>@starting-style</code> —— 浏览器在首次渲染前读入起点样式，与终态形成差值，过渡自动发生；<code>allow-discrete</code> 让 <code>display</code> 和 <code>overlay</code> 也能参与过渡。像素酱发现连 Popover 的进出场都能零 JS 完成。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>传统方案命令式拆帧：<code>classList.add(&#39;enter&#39;)</code> → <code>rAF</code> → <code>remove</code>。<code>display: none</code> 切换更麻烦：先显示、强制 reflow、再写终态。叠加痛苦：Popover 弹出瞬间闪现、离场动画等 <code>setTimeout</code>、CSS 时长与 JS 定时器双写，改一处忘另一处就出 bug。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>@starting-style</code> 凭空造一帧：浏览器在元素首次参与样式计算时，把起点声明当作「第 0 帧」，与常规样式形成差值 → 过渡自然发生。<code>transition-behavior: allow-discrete</code> 让 <code>display</code>、<code>overlay</code> 这些离散属性延迟到过渡结束才切换，离场动画播完再隐藏。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：新节点自动入场、display 切换平滑过渡、Popover 零 JS 进出场、Toast <code>transitionend</code> 自动清理。记住边界：<code>@starting-style</code> 只对<strong>首次渲染</strong>生效，已渲染过的元素改样式不会重新触发。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>@starting-style 只在首次渲染时生效：已渲染过的元素改样式不会重新触发。</li><li>display/overlay 必须加 allow-discrete，否则动画播到一半元素就消失。</li><li>与 Popover 是黄金搭档：<code>:popover-open</code> 起点 + <code>:not(:popover-open)</code> 离场态，零 JS 进出场。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 <code>@starting-style</code> 里写 <code>display: none</code> 没有意义？</p><p><strong>答</strong>：元素要参与渲染才能过渡。<code>display: none</code> 的元素不生成盒模型，没有「前一帧」可供插值。起点规则里应该写 <code>opacity</code>、<code>translate</code> 等可动画属性，<code>display</code> 留在常规声明里由 <code>allow-discrete</code> 延迟切换。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>新节点入场 + display 切换 + Popover 进出场 + Toast 自动消失 + 嵌套写法：<a href="./../../examples/css/22-starting-style/index-01-starting-style.html">examples/css/22-starting-style/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 34 话《Observer 三件套》——IntersectionObserver / ResizeObserver / MutationObserver：浏览器原生推送替代轮询，懒加载、无限滚动、响应式组件、水印防删，全部零 scroll 监听。</p>',22)])])}const y=a(s,[["render",d]]);export{u as __pageData,y as default};
